/**
 * Edition index — DOCS/ARCHITECTURE/L-bookstore-commerce-20261106.md §2.5.
 * `content/library/editions.json` is generated by BA.1 (`scripts/build-modules.mjs`), never hand-edited.
 * Read through import.meta.glob so an absent file yields an empty index (Catena then reads
 * `unavailable` — the honest pre-BA.1 state; no placeholder value anywhere).
 */
import type { EditionRecord } from './types.ts';

export interface EditionIndex {
  get(id: string): EditionRecord | null;
  all(): EditionRecord[];
}

interface EditionsFile { schemaVersion: 1; editions: EditionRecord[] }

const files = import.meta.glob<EditionsFile>('/content/library/editions.json', { eager: true, import: 'default' });

export function loadEditions(): EditionIndex {
  const file = Object.values(files)[0];
  const list: EditionRecord[] = file && file.schemaVersion === 1 && Array.isArray(file.editions) ? file.editions : [];
  const byId = new Map(list.map((e) => [e.id, e]));
  return {
    get: (id) => byId.get(id) ?? null,
    all: () => list.slice(),
  };
}
